/** The winning side's MVP, for stories told from one player's point of view. */
export const MVP = MATCH_CARD.mvp as ParticipantView;

/** The losing side's ACE. */
export const ACE = MATCH_CARD.ace as ParticipantView;

/** A player with neither badge, whose score shows their place instead. */
export const UNBADGED = [
  ...MATCH_CARD.blue.participants,
  ...MATCH_CARD.red.participants,
].find((p) => p.badge === null && p.opScore != null) as ParticipantView;

/** The card on the MVP's profile. */
export const MATCH_CARD_FOR_MVP: MatchCardView = { ...MATCH_CARD, player: MVP };

/** The card on the ACE's profile. */
export const MATCH_CARD_FOR_ACE: MatchCardView = { ...MATCH_CARD, player: ACE };
